<?php
require_once __DIR__ . '/payment-common.php';
$HBL_SANDBOX_SESSION_PATH='/api/checkout/v1/session';$HBL_LIVE_SESSION_PATH='/api/checkout/v1/session';$HBL_SANDBOX_PORTAL_PATH='/checkout/';$HBL_LIVE_PORTAL_PATH='/checkout/';
function hbl_config(): array{$live=strtolower(app_env('HBL_ENV','sandbox'))==='live';return['base'=>rtrim(app_env('HBL_BASE_URL'),'/'),'session'=>$live?$GLOBALS['HBL_LIVE_SESSION_PATH']:$GLOBALS['HBL_SANDBOX_SESSION_PATH'],'portal'=>$live?$GLOBALS['HBL_LIVE_PORTAL_PATH']:$GLOBALS['HBL_SANDBOX_PORTAL_PATH']];}
function hbl_sign(string $json): string{$p=app_env('HBL_PRIVATE_KEY_PATH');$pem=$p!==''&&is_file($p)?file_get_contents($p):false;$key=$pem?openssl_pkey_get_private($pem,app_env('HBL_PASSWORD')):false;if(!$key)throw new RuntimeException('HBL private key is unavailable');$sig='';if(!openssl_sign($json,$sig,$key,OPENSSL_ALGO_SHA256))throw new RuntimeException('HBL request signing failed');return base64_encode($sig);}
function hbl_verify(array $data): bool{$sig=(string)($data['signature']??$data['SIGNATURE']??'');$p=app_env('HBL_PUBLIC_KEY_PATH');$pem=$p!==''&&is_file($p)?file_get_contents($p):false;if(!$pem||$sig==='')return false;unset($data['signature'],$data['SIGNATURE']);ksort($data,SORT_STRING);return openssl_verify(json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),base64_decode($sig),$pem,OPENSSL_ALGO_SHA256)===1;}
function hbl_callback(): void{if(!hbl_verify($_POST))api_json(400,['ok'=>false,'error'=>'HBL response signature verification failed']);$no=(string)($_POST['reference']??$_POST['REFERENCE']??$_POST['order_no']??'');$status=strtoupper((string)($_POST['status']??$_POST['STATUS']??''));$paid=$no!==''&&in_array($status,['SUCCESS','PAID','0000'],true);if($paid)mark_order_paid($no,(string)($_POST['transactionId']??$_POST['TRANSACTION_ID']??$no));header('Location: '.rtrim(app_env('APP_URL'),'/').'/checkout.html?payment='.($paid?'paid':'pending').'&order_no='.rawurlencode($no));exit;}
if(($_GET['action']??'')==='return'){if(($_SERVER['REQUEST_METHOD']??'')!=='POST')api_json(405,['ok'=>false,'error'=>'Invalid callback method']);hbl_callback();}
api_method('POST');if(app_env('HBL_ENABLED','false')!=='true')api_json(403,['ok'=>false,'error'=>'Meezan card checkout is disabled']);$cfg=hbl_config();if($cfg['base']==='')api_json(503,['ok'=>false,'error'=>'Set HBL_BASE_URL']);try{$order=payment_order((string)(api_input()['order_no']??''));if($order['payment_method']!=='meezan')api_json(422,['ok'=>false,'error'=>'Order payment method mismatch']);$payload=['ORDER'=>['SUBTOTAL'=>(int)$order['total'],'DISCOUNT_ON_TOTAL'=>0,'reference'=>$order['order_no'],'returnUrl'=>app_env('HBL_RETURN_URL',rtrim(app_env('APP_URL'),'/').'/api/hbl.php?action=return'),'cancelUrl'=>app_env('HBL_CANCEL_URL',rtrim(app_env('APP_URL'),'/').'/checkout.html?payment=cancelled')]];$json=json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$request=['payload'=>$payload,'signature'=>hbl_sign($json),'userId'=>app_env('HBL_USER_ID'),'password'=>app_env('HBL_PASSWORD'),'channel'=>app_env('HBL_CHANNEL')];$r=gateway_post($cfg['base'].$cfg['session'],['Content-Type: application/json','Accept: application/json'],json_encode($request));$session=(string)($r['data']['SESSION_ID']??$r['data']['sessionId']??'');if($session==='')api_json(502,['ok'=>false,'error'=>'HBL did not return a checkout session']);api_json(200,['ok'=>true,'url'=>$cfg['base'].$cfg['portal'].'?SESSION_ID='.rawurlencode($session)]);}catch(Throwable $e){api_json(502,['ok'=>false,'error'=>$e->getMessage()]);}
